<style lang="scss" scoped>
  @use '~/assets/style/mixins.scss' as *;

  .cookie {
    @include flex-nowrap;
    justify-content: center;
    gap: 14px;
    &-wrapper {
      position: fixed;
      left: 50%;
      bottom: 25px;
      transform: translateX(-50%);
      max-width: 100%;
      padding: 20px 25px;
      border: 1px solid var(--modal-cookie-border-color);
      background-color: var(--block-main-bg-color);
      box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
      border-radius: 25px;
      z-index: 10000;
      @include transition-theme(all);
      @media (max-width: 450px) {
        padding: 10px 15px;
      }
    }
    &__description {
      @include transition-theme(color);
      color: var(--text-color);
      font-family: var(--bold-font-family);
      font-size: 18px;
      margin-bottom: 11px;
      white-space: nowrap;
      @media (max-width: 450px) {
        font-size: 16px;
        margin-bottom: 8px;
      }
    }
    &__accept {
      cursor: pointer;
      border-radius: 13px;
      border: none;
      background-color: var(--cookie-bg-color);
      width: 100%;
      height: 27px;
      color: var(--cookie-text-color);
      font-family: var(--medium-font-family);
      font-size: 14px;
      transition: all .2s ease;
      &:hover {
        opacity: 0.85;
      }
      @media (max-width: 450px) {
        height: 30px;
      }
    }
    &__svg {
      @media (max-width: 450px) {
        width: 70px;
      }
    }
  }
</style>